    @Before
    public void before(){
        instance = new ComplexFormat();
    }

    @Test
    public void testParse() throws Exception{
        // Test case 1: real number
        Complex result = instance.parse("1.0", new ParsePosition(0));
        Assert.assertEquals(1.0, result.getReal(), 0.01);
        Assert.assertEquals(0.0, result.getImaginary(), 0.01);

        // Test case 2: imaginary number
        result = instance.parse("1.0i", new ParsePosition(0));
        Assert.assertEquals(0.0, result.getReal(), 0.01);
        Assert.assertEquals(1.0, result.getImaginary(), 0.01);

        // Test case 3: complex number
        result = instance.parse("1.0+1.0i", new ParsePosition(0));
        Assert.assertEquals(1.0, result.getReal(), 0.01);
        Assert.assertEquals(1.0, result.getImaginary(), 0.01);

        // Test case 4: complex number with negative imaginary part
        result = instance.parse("1.0-1.0i", new ParsePosition(0));
        Assert.assertEquals(1.0, result.getReal(), 0.01);
        Assert.assertEquals(-1.0, result.getImaginary(), 0.01);

        // Test case 5: invalid input
        try {
            instance.parse("", new ParsePosition(0));
            Assert.fail();
        } catch (ParseException e) {
            // expected
        }
    }

    @Test
    public void testParseException() throws Exception{
        // Test case 1: empty string
        try {
            instance.parse("");
            Assert.fail();
        } catch (ParseException e) {
            Assert.assertEquals("Unparseable complex number: \"\"", e.getMessage());
        }

        // Test case 2: invalid input
        try {
            instance.parse("abc");
            Assert.fail();
        } catch (ParseException e) {
            Assert.assertTrue(e.getMessage().startsWith("Unparseable complex number: \""));
        }
    }

    @Test
    public void testConstructors(){
        // Test case 1: default constructor
        ComplexFormat instance1 = new ComplexFormat();
        Assert.assertNotNull(instance1);

        // Test case 2: constructor with NumberFormat
        NumberFormat format = NumberFormat.getInstance();
        ComplexFormat instance2 = new ComplexFormat(format);
        Assert.assertNotNull(instance2);

        // Test case 3: constructor with NumberFormat for real and imaginary parts
        ComplexFormat instance3 = new ComplexFormat(format, format);
        Assert.assertNotNull(instance3);

        // Test case 4: constructor with imaginary character
        ComplexFormat instance4 = new ComplexFormat("j");
        Assert.assertNotNull(instance4);

        // Test case 5: constructor with imaginary character and NumberFormat
        ComplexFormat instance5 = new ComplexFormat("j", format);
        Assert.assertNotNull(instance5);

        // Test case 6: constructor with imaginary character, real and imaginary NumberFormat
        ComplexFormat instance6 = new ComplexFormat("j", format, format);
        Assert.assertNotNull(instance6);
    }

    @Test
    public void testGetters(){
        // Test case 1: getImaginaryCharacter
        instance.setImaginaryCharacter("j");
        Assert.assertEquals("j", instance.getImaginaryCharacter());

        // Test case 2: getImaginaryFormat
        NumberFormat format = NumberFormat.getInstance();
        instance.setImaginaryFormat(format);
        Assert.assertEquals(format, instance.getImaginaryFormat());

        // Test case 3: getRealFormat
        instance.setRealFormat(format);
        Assert.assertEquals(format, instance.getRealFormat());
    }

    @Test
    public void testSetters(){
        // Test case 1: setImaginaryCharacter
