import org.apache.commons.math3.util.MathArrays;

public class MultivariateNormalDistributionTest{
private MultivariateNormalDistribution distribution;
    @Rule
    public ExpectedException exception = ExpectedException.none();

    @Before
    public void init(){
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        distribution = new MultivariateNormalDistribution(means, covariances);
    }

    @Test
    public void testConstructor(){
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        distribution = new MultivariateNormalDistribution(means, covariances);
        assertNotNull(distribution);
    }

    @Test
    public void testConstructorWithRandomGenerator(){
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        RandomGenerator rng = new Well19937c();
        distribution = new MultivariateNormalDistribution(rng, means, covariances);
        assertNotNull(distribution);
    }

    @Test
    public void testGetMeans(){
        double[] means = distribution.getMeans();
        assertNotNull(means);
        assertEquals(2, means.length);
    }

    @Test
    public void testGetCovariances(){
        RealMatrix covariances = distribution.getCovariances();
        assertNotNull(covariances);
        assertEquals(2, covariances.getRowDimension());
    }

    @Test
    public void testGetStandardDeviations(){
        double[] stdDev = distribution.getStandardDeviations();
        assertNotNull(stdDev);
        assertEquals(2, stdDev.length);
    }

    @Test
    public void testSample(){
        double[] sample = distribution.sample();
        assertNotNull(sample);
        assertEquals(2, sample.length);
    }

    @Test
    public void testDensity() throws Exception {
        double[] vals = {0.0, 0.0};
        double density = distribution.density(vals);
        assertNotNull(density);
        assertTrue(FastMath.isFinite(density));
    }

    @Test
    public void testDensity_DimensionMismatchException() throws Exception {
        exception.expect(DimensionMismatchException.class);
        double[] vals = {0.0};
        distribution.density(vals);
    }

    @Test
    public void testMultivariateNormalDistribution_SingularMatrixException(){
        exception.expect(SingularMatrixException.class);
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 1.0}, {1.0, 1.0}};
        new MultivariateNormalDistribution(means, covariances);
    }

    @Test
    public void testMultivariateNormalDistribution_DimensionMismatchException(){
        exception.expect(DimensionMismatchException.class);
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}};
        new MultivariateNormalDistribution(means, covariances);
    }

    @Test
    public void testMultivariateNormalDistribution_NonPositiveDefiniteMatrixException(){
        exception.expect(NonPositiveDefiniteMatrixException.class);
        double[] means = {0.0, 0.0};
        double[][] covariances = {{-1.0, 0.0}, {0.0, 1.0}};
        new MultivariateNormalDistribution(means, covariances);
    }
}
