import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;

public class HypergeometricDistributionTest{
private HypergeometricDistribution hypergeometricDistribution;
    @Rule
    public ExpectedException expectedEx = ExpectedException.none();

    @Before
    public void init(){
        hypergeometricDistribution = new HypergeometricDistribution(100, 50, 30);
    }

    @Test
    public void testGetNumericalMean() throws Exception {
        Assert.assertEquals(15, hypergeometricDistribution.getNumericalMean(), 1.0e-12);
        hypergeometricDistribution = new HypergeometricDistribution(1000, 500, 300);
        Assert.assertEquals(150, hypergeometricDistribution.getNumericalMean(), 1.0e-12);
    }

    @Test
    public void testConstructor() throws Exception {
        hypergeometricDistribution = new HypergeometricDistribution(100, 50, 30);
        Assert.assertNotNull(hypergeometricDistribution);
        hypergeometricDistribution = new HypergeometricDistribution(new Well19937c(), 100, 50, 30);
        Assert.assertNotNull(hypergeometricDistribution);
    }

    @Test
    public void testConstructorException1() throws Exception {
        expectedEx.expect(NotStrictlyPositiveException.class);
        expectedEx.expectMessage(LocalizedFormats.POPULATION_SIZE);
        hypergeometricDistribution = new HypergeometricDistribution(0, 50, 30);
    }

    @Test
    public void testConstructorException2() throws Exception {
        expectedEx.expect(NotPositiveException.class);
        expectedEx.expectMessage(LocalizedFormats.NUMBER_OF_SUCCESSES);
        hypergeometricDistribution = new HypergeometricDistribution(100, -10, 30);
    }

    @Test
    public void testConstructorException3() throws Exception {
        expectedEx.expect(NotPositiveException.class);
        expectedEx.expectMessage(LocalizedFormats.NUMBER_OF_SAMPLES);
        hypergeometricDistribution = new HypergeometricDistribution(100, 50, -30);
    }

    @Test
    public void testConstructorException4() throws Exception {
        expectedEx.expect(NumberIsTooLargeException.class);
        expectedEx.expectMessage(LocalizedFormats.NUMBER_OF_SUCCESS_LARGER_THAN_POPULATION_SIZE);
        hypergeometricDistribution = new HypergeometricDistribution(100, 150, 30);
    }

    @Test
    public void testConstructorException5() throws Exception {
        expectedEx.expect(NumberIsTooLargeException.class);
        expectedEx.expectMessage(LocalizedFormats.SAMPLE_SIZE_LARGER_THAN_POPULATION_SIZE);
        hypergeometricDistribution = new HypergeometricDistribution(100, 50, 150);
    }

    @Test
    public void testGetPopulationSize() throws Exception {
        Assert.assertEquals(100, hypergeometricDistribution.getPopulationSize());
    }

    @Test
    public void testGetNumberOfSuccesses() throws Exception {
        Assert.assertEquals(50, hypergeometricDistribution.getNumberOfSuccesses());
    }

    @Test
    public void testGetSampleSize() throws Exception {
        Assert.assertEquals(30, hypergeometricDistribution.getSampleSize());
    }

    @Test
    public void testGetSupportLowerBound() throws Exception {
        Assert.assertEquals( FastMath.max(0, hypergeometricDistribution.getSampleSize() + hypergeometricDistribution.getPopulationSize() - hypergeometricDistribution.getNumberOfSuccesses()), hypergeometricDistribution.getSupportLowerBound());
    }

    @Test
    public void testGetSupportUpperBound() throws Exception {
        Assert.assertEquals(FastMath.min(hypergeometricDistribution.getSampleSize(), hypergeometricDistribution.getNumberOfSuccesses()), hypergeometricDistribution.getSupportUpperBound());
    }
}
