                return state;
            }

            @Override
            public double[] mapDoubleArrayToStateAndDerivative(double t, double[] data) {
                return data;
            }
        });

        // Perform integration
        integrator.integrate(equations, 1.0);

        // Check result
        Assert.assertEquals(1.0,equations.getTime(),1.0e-12);
        Assert.assertArrayEquals(new double[]{1.0},equations.getCompleteState(),1.0e-12);
    }

