import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.io.Serializable;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.util.MathUtils;

public class VarianceTest{
private Variance variance;

    @Before
    public void init(){
        variance = new Variance();
    }

    @Test
    public void testEvaluate_NaN(){
        double[] values = new double[]{Double.NaN};
        int begin = 0;
        int length = 1;
        double result = variance.evaluate(values, begin, length);
        assertTrue(Double.isNaN(result));
    }

    @Test
    public void testEvaluate_Length1(){
        double[] values = new double[]{1.0};
        int begin = 0;
        int length = 1;
        double result = variance.evaluate(values, begin, length);
        assertEquals(0.0, result, 0.0);
    }

    @Test
    public void testEvaluate_Length2(){
        double[] values = new double[]{1.0, 2.0};
        int begin = 0;
        int length = 2;
        double result = variance.evaluate(values, begin, length);
        assertEquals(0.5, result, 0.0);
    }

    @Test
    public void testEvaluate_EmptyArray(){
        double[] values = new double[]{};
        int begin = 0;
        int length = 0;
        double result = variance.evaluate(values, begin, length);
        assertTrue(Double.isNaN(result));
    }

    @Test
    public void testEvaluate_NullArray(){
        double[] values = null;
        int begin = 0;
        int length = 1;
        try{
            variance.evaluate(values, begin, length);
            fail("Expect NullArgumentException");
        }catch (NullArgumentException e){
            //expected
        }
    }

    @Test
    public void testEvaluate_BeginOutOfBounds(){
        double[] values = new double[]{1.0};
        int begin = 1;
        int length = 1;
        try{
            variance.evaluate(values, begin, length);
            fail("Expect ArrayIndexOutOfBoundsException");
        }catch (ArrayIndexOutOfBoundsException e){
            //expected
        }
    }

    @Test
    public void testEvaluate_LengthOutOfBounds(){
        double[] values = new double[]{1.0};
        int begin = 0;
        int length = 2;
        try{
            variance.evaluate(values, begin, length);
            fail("Expect ArrayIndexOutOfBoundsException");
        }catch (ArrayIndexOutOfBoundsException e){
            //expected
        }
    }

    @Test
    public void testGetN(){
        variance.increment(1.0);
        variance.increment(2.0);
        assertEquals(2, variance.getN());
    }

    @Test
    public void testGetResult(){
        variance.increment(1.0);
        variance.increment(2.0);
        double result = variance.getResult();
        assertEquals(0.5, result, 0.0);
    }

    @Test
    public void testClear(){
        variance.increment(1.0);
        variance.increment(2.0);
        variance.clear();
        assertEquals(0, variance.getN());
        assertTrue(Double.isNaN(variance.getResult()));
    }

    @Test
    public void testIsBiasCorrected(){
        assertTrue(variance.isBiasCorrected());
        variance.setBiasCorrected(false);
        assertFalse(variance.isBiasCorrected());
    }

    @Test
    public void testCopy(){
        Variance original = new Variance();
        original.increment(1.0);
        original.increment(2.0);
        Variance copy = original.copy();
        assertEquals(original.getN(), copy.getN());
        assertEquals(original.getResult(), copy.getResult(), 0.0);
    }

    @Test
    public void testStaticCopy(){
        Variance original = new Variance();
        original.increment(1.0);
        original.increment(2.0);
        Variance dest = new Variance();
        Variance.copy(original, dest);
        assertEquals(original.getN(), dest.getN());
        assertEquals(original.getResult(), dest.getResult(), 0.0);
    }
}
