import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.util.MathUtils;

public class VarianceTest{
private Variance instance;

    @Before
    public void setUp(){
        instance = new Variance();
    }

    @After
    public void tearDown(){
    }

    @Test
    public void testEvaluateDoubleArrayDoubleArrayDouble() {
        double[] values = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 1.0, 1.0};
        double mean = 2.0;
        double result = instance.evaluate(values, weights, mean);
        assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testEvaluateDoubleArrayDoubleArrayDoubleBeginLength() {
        double[] values = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 1.0, 1.0};
        double mean = 2.0;
        double result = instance.evaluate(values, weights, mean, 0, values.length);
        assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testEvaluateDoubleArrayDoubleBeginLength() {
        double[] values = {1.0, 2.0, 3.0};
        double mean = 2.0;
        double result = instance.evaluate(values, mean, 0, values.length);
        assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testEvaluateDoubleArrayDouble() {
        double[] values = {1.0, 2.0, 3.0};
        double mean = 2.0;
        double result = instance.evaluate(values, mean);
        assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testEvaluateDoubleArrayDoubleArray() {
        double[] values = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 1.0, 1.0};
        double result = instance.evaluate(values, weights);
        assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testEvaluateDoubleArray() {
        double[] values = {1.0, 2.0, 3.0};
        double result = instance.evaluate(values);
        assertEquals(1.0, result, 0.0);
    }

    @Test(expected = NullArgumentException.class)
    public void testEvaluateDoubleArrayDoubleArrayNull() {
        double[] values = null;
        double[] weights = {1.0, 1.0, 1.0};
        double mean = 2.0;
        instance.evaluate(values, weights, mean);
    }

    @Test(expected = NullArgumentException.class)
    public void testEvaluateDoubleArrayNullDouble() {
        double[] values = null;
        double mean = 2.0;
        instance.evaluate(values, mean);
    }

    @Test(expected = NullArgumentException.class)
    public void testEvaluateDoubleArrayNullDoubleArray() {
        double[] values = null;
        double[] weights = {1.0, 1.0, 1.0};
        instance.evaluate(values, weights);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEvaluateDoubleArrayDoubleArrayLengthMismatch() {
        double[] values = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 1.0};
        double mean = 2.0;
        instance.evaluate(values, weights, mean);
    }

    @Test
    public void testIsBiasCorrected() {
        assertTrue(instance.isBiasCorrected());
        instance.setBiasCorrected(false);
        assertFalse(instance.isBiasCorrected());
    }

    @Test
    public void testCopy() {
        Variance original = new Variance();
        original.increment(1.0);
        Variance copy = original.copy();
        assertEquals(original.getResult(), copy.getResult(), 0.0);
    }

    @Test
    public void testGetResult() {
        instance.increment(1.0);
        assertEquals(0.0, instance.getResult(), 0.0);
    }

    @Test
    public void testGetN() {
        instance.increment(1.0);
        assertEquals(1, instance.getN());
    }

    @Test
    public void testClear() {
        instance.increment(1.0);
        instance.clear();
        assertEquals(0.0, instance.getResult(), 0.0);
        assertEquals(0, instance.getN());
    }
}
