    public void testDivide_NaN_Divisor(){
        Complex result = Complex.NaN.divide(Double.NaN);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NaN_Divisor_normal(){
        Complex result = Complex.NaN.divide(2);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_normal_Divisor_NaN(){
        Complex result = Complex.ONE.divide(Double.NaN);
        Assert.assertTrue(result.isNaN());
    }

    @Test
