        Complex result = Complex.ZERO.divide(0);
        Assert.assertEquals(Complex.NaN, result);
    }

    @Test
    public void testDivide_Infinite_Divisor_notInfinite_complex(){
        Complex result = Complex.ONE.divide(Double.POSITIVE_INFINITY);
        Assert.assertEquals(Complex.ZERO, result);
    }

    @Test
    public void testDivide_Infinite_Divisor_Infinite_complex(){
        Complex result = Complex.INF.divide(Double.POSITIVE_INFINITY);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_normal(){
        Complex result = Complex.ONE.divide(2);
        Assert.assertEquals(Complex.valueOf(0.5, 0), result);
    }

    @Test
    public void testDivide_normal_Complex(){
        Complex result = Complex.ONE.divide(Complex.ONE);
        Assert.assertEquals(Complex.ONE, result);
    }
}
