import org.junit.Test;
import org.junit.Assert;
import org.junit.Before;
import org.junit.After; 
import org.junit.Assert.*;
import org.junit.Ignore;
import org.junit.BeforeClass;
import org.junit.AfterClass;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.util.Arrays;
import org.apache.commons.math.FieldElement;

public class DfpTest{
private Dfp dfp;
    private DfpField field;

    @Before
    public void setUp(){
        field = new DfpField();
        dfp = new Dfp(field);
    }

    @Test
    public void testToDouble_Infinite(){
        Dfp infinite = new Dfp(field, Double.POSITIVE_INFINITY);
        Assert.assertEquals(Double.POSITIVE_INFINITY, infinite.toDouble(), 0);
        infinite = new Dfp(field, Double.NEGATIVE_INFINITY);
        Assert.assertEquals(Double.NEGATIVE_INFINITY, infinite.toDouble(), 0);
    }

    @Test
    public void testToDouble_NaN(){
        Dfp nan = new Dfp(field, Double.NaN);
        Assert.assertTrue(Double.isNaN(nan.toDouble()));
    }

    @Test
    public void testToDouble_Zero(){
        Dfp zero = new Dfp(field, 0);
        Assert.assertEquals(0.0, zero.toDouble(), 0);
        zero = new Dfp(field, -0.0);
        Assert.assertEquals(-0.0, zero.toDouble(), 0);
    }

    @Test
    public void testToDouble_Subnormal(){
        Dfp subnormal = new Dfp(field, 1e-323);
        Assert.assertNotEquals(0.0, subnormal.toDouble(), 0);
    }

    @Test
    public void testToDouble_Normal(){
        Dfp normal = new Dfp(field, 1.5);
        Assert.assertEquals(1.5, normal.toDouble(), 0);
    }

    @Test
    public void testToDouble_Overflow(){
        Dfp overflow = new Dfp(field, 1e309);
        Assert.assertEquals(Double.POSITIVE_INFINITY, overflow.toDouble(), 0);
    }

    @Test
    public void testToDouble_SpecialCases(){
        Dfp special = new Dfp(field, "1.7976931348623157E308");
        Assert.assertEquals(Double.POSITIVE_INFINITY, special.toDouble(), 0);
        special = new Dfp(field, "-1.7976931348623157E308");
        Assert.assertEquals(Double.NEGATIVE_INFINITY, special.toDouble(), 0);
    }
}
