@Rule
    public final ExpectedException expectedEx = ExpectedException.none();
    private GaussNewtonOptimizer instance;
    private ConvergenceChecker<PointVectorValuePair> mockChecker;

    @Before
    public void setUp() {
        mockChecker = mock(ConvergenceChecker.class);
        instance = new GaussNewtonOptimizer(mockChecker);
    }

    @Test(expected = NullArgumentException.class)
    public void testNullChecker() {
        instance = new GaussNewtonOptimizer(null);
    }

    @Test
    public void testCheckParameters() {
        instance.checkParameters();
        // No exception expected
    }

    @Test(expected = ConvergenceException.class)
    public void testSingularMatrix() {
        // Mock a singular matrix
        RealMatrix mockMatrix = mock(RealMatrix.class);
        when(mockMatrix.getRowDimension()).thenReturn(2);
        when(mockMatrix.getColumnDimension()).thenReturn(2);
        DecompositionSolver mockSolver = mock(DecompositionSolver.class);
        when(mockSolver.solve(any())).thenThrow(SingularMatrixException.class);

        // Call doOptimize
        instance.doOptimize();
        // Exception expected
    }

    @Test(expected = MathInternalError.class)
    public void testMathInternalError() {
        // Mock a checker that never converges
        when(mockChecker.converged(anyInt(), any(PointVectorValuePair.class), any(PointVectorValuePair.class))).thenReturn(false);
        instance.doOptimize();
        // Exception expected
    }

