        when(mockChecker.converged(anyInt(), eq(mockPair1), eq(mockPair2))).thenReturn(true);

        // Call doOptimize
        PointVectorValuePair result = instance.doOptimize();
        assertNotNull(result);
    }

    @Test
    public void testNotConverged() {
        // Mock a checker that never converges
        when(mockChecker.converged(anyInt(), any(PointVectorValuePair.class), any(PointVectorValuePair.class))).thenReturn(false);

        // Call doOptimize
        expectedEx.expect(MathInternalError.class);
        instance.doOptimize();
    }

    @Test
    public void testLUDecomposition() {
        instance = new GaussNewtonOptimizer(true, mockChecker);
        instance.doOptimize();
    }

    @Test
    public void testQRDecomposition() {
        instance = new GaussNewtonOptimizer(false, mockChecker);
        instance.doOptimize();
    }

    @Test
    public void testIncrementIterationCount() {
        instance.incrementIterationCount();
        // No exception expected
    }
}
