public class BrentSolverTest{
private BrentSolver solver;
    private UnivariateRealFunction f;

    @Before
    public void init(){
        f = new UnivariateRealFunction() {
            @Override
            public double value(double x) throws FunctionEvaluationException {
                return x*x - 4;
            }
        };
        solver = new BrentSolver(f);
    }

    @Test(expected = NullPointerException.class)
    public void testSolveWhenFNullAndMinMax() throws Exception {
        solver = new BrentSolver();
        solver.solve(null, 1, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolveWhenMinMaxInvalid() throws Exception {
        solver.solve(f, 4, 1);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testSolveWhenFunctionEvaluationException() throws Exception {
        f = new UnivariateRealFunction() {
            @Override
            public double value(double x) throws FunctionEvaluationException {
                throw new FunctionEvaluationException(x);
            }
        };
        solver.solve(f, 1, 4);
    }

    @Test(expected = MaxIterationsExceededException.class)
    public void testSolveWhenMaxIterationExceededException() throws Exception {
        f = new UnivariateRealFunction() {
            @Override
            public double value(double x) throws FunctionEvaluationException {
                return 1;
            }
        };
        solver.solve(f, 1, 4);
    }

    @Test
    public void testSolveWhenSucceed() throws Exception {
        assertEquals(2, solver.solve(f, -4, 4), 1e-6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolveWhenMinEqualsMax() throws Exception {
        solver.solve(f, 2, 2);
    }

    @Test
    public void testSolveWhenMinBiggerThanZeroAndMaxBiggerThanMin() throws Exception {
        assertEquals(2, solver.solve(f, 1, 4), 1e-6);
    }

    @Test
    public void testSolveWhenMinLessThanZeroAndMaxBiggerThanMin() throws Exception {
        assertEquals(-2, solver.solve(f, -4, -1), 1e-6);
    }

    @Test
    public void testSolveWhenMinBiggerThanZeroAndMaxLessThanMin() throws Exception {
        try {
            solver.solve(f, 4, 1);
            Assert.fail();
        } catch (IllegalArgumentException e) {}
    }

    @Test
    public void testSolveWhenBothMinAndMaxLessThanZero() throws Exception {
        assertEquals(-2, solver.solve(f, -4, -1), 1e-6);
    }
}
