    public void testGetPct_Char_ZeroValues(){
        Frequency frequency = new Frequency();
        Assert.assertEquals(0.0, frequency.getPct((char) 1), 0.01);
    }

    @Test
    public void testGetPct_Char_Null(){
        Frequency frequency = new Frequency();
        try{
            frequency.getPct('\u0000');
            Assert.fail("Should throw NullPointerException or alike");
        }catch(Exception e){
            //OK
        }
    }

    @Test
    public void testGetPct_Char_SameAsGetPctComparable(){
        Frequency frequency = new Frequency();
        frequency.addValue((char) 1);
        Assert.assertEquals(frequency.getPct(Character.valueOf((char) 1)), frequency.getPct((char) 1), 0.01);
    }
}
