    public void testBracket_NullFunction() throws Exception {
        UnivariateRealSolverUtils.bracket(null, 1.0, 2.0, 3.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBracket_WrongBounds() throws Exception {
        when(f.value(1.0)).thenReturn(-1.0);
        UnivariateRealSolverUtils.bracket(f, 1.0, 2.0, 1.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBracket_WrongBounds2() throws Exception {
        when(f.value(1.0)).thenReturn(1.0);
        UnivariateRealSolverUtils.bracket(f, 1.0, 2.0, 2.0);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testBracket_FunctionEvaluationException() throws Exception {
        when(f.value(1.0)).thenThrow(new MathRuntimeException(""));
        UnivariateRealSolverUtils.bracket(f, 1.0, 0.0, 2.0);
    }

    @Test(expected = ConvergenceException.class)
    public void testBracket_ConvergenceException() throws Exception {
        when(f.value(1.0)).thenReturn(1.0);
        when(f.value(2.0)).thenReturn(1.0);
        UnivariateRealSolverUtils.bracket(f, 1.0, 0.0, 2.0);
    }

    @Test
    public void testBracket_OK() throws Exception {
        when(f.value(1.0)).thenReturn(-1.0);
        when(f.value(2.0)).thenReturn(1.0);
