import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.io.Serializable;
import java.text.NumberFormat;
import java.util.Iterator;
import java.util.Comparator;
import java.util.TreeMap;

public class FrequencyTest{
private Frequency frequency;

    @Before
    public void setup() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValue() {
        frequency.addValue("test");
        Assert.assertEquals(1, frequency.getCount("test"));
    }

    @Test
    public void testAddValue_Null() {
        try {
            frequency.addValue(null);
            Assert.fail("NullPointerException expected");
        } catch (NullPointerException e) {
            // expected
        }
    }

    @Test
    public void testAddValue_Comparable() {
        frequency.addValue((Comparable) "test");
        Assert.assertEquals(1, frequency.getCount("test"));
    }

    @Test
    public void testAddValue_Repeated() {
        frequency.addValue("test");
        frequency.addValue("test");
        Assert.assertEquals(2, frequency.getCount("test"));
    }

    @Test
    public void testAddValue_DifferentTypes() {
        frequency.addValue("test");
        frequency.addValue(1);
        frequency.addValue(1L);
        frequency.addValue((char) 1);
        Assert.assertEquals(1, frequency.getCount("test"));
        Assert.assertEquals(1, frequency.getCount(1));
        Assert.assertEquals(1, frequency.getCount(1L));
        Assert.assertEquals(1, frequency.getCount((char) 1));
    }

    @Test
    public void testGetCount() {
        frequency.addValue("test");
        Assert.assertEquals(1, frequency.getCount("test"));
    }

    @Test
    public void testGetCount_NotExisting() {
        Assert.assertEquals(0, frequency.getCount("not existing"));
    }

    @Test
    public void testGetSumFreq() {
        frequency.addValue("test");
        frequency.addValue("test");
        Assert.assertEquals(2, frequency.getSumFreq());
    }

    @Test
    public void testGetPct() {
        frequency.addValue("test");
        frequency.addValue("test");
        Assert.assertEquals(0.5, frequency.getPct("test"), 0.01);
    }

    @Test
    public void testGetCumFreq() {
        frequency.addValue("test");
        frequency.addValue("test2");
        frequency.addValue("test");
        Assert.assertEquals(2, frequency.getCumFreq("test"));
    }

    @Test
    public void testGetCumPct() {
        frequency.addValue("test");
        frequency.addValue("test2");
        frequency.addValue("test");
        Assert.assertEquals(2.0 / 3.0, frequency.getCumPct("test"), 0.01);
    }

    @Test
    public void testClear() {
        frequency.addValue("test");
        frequency.clear();
        Assert.assertEquals(0, frequency.getCount("test"));
    }

    @Test
    public void testValuesIterator() {
        frequency.addValue("test");
        Iterator iterator = frequency.valuesIterator();
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals("test", iterator.next());
    }

    @Test
    public void testToString() {
        frequency.addValue("test");
        String str = frequency.toString();
        Assert.assertNotNull(str);
        Assert.assertTrue(str.contains("test"));
    }

    @Test
    public void testFrequency_Comparator() {
        Comparator comparator = (o1, o2) -> ((String) o1).compareToIgnoreCase((String) o2);
        Frequency frequency = new Frequency(comparator);
        frequency.addValue("Test");
        frequency.addValue("test");
        Assert.assertEquals(2, frequency.getSumFreq());
    }

    @Test
    public void testFrequency_NoArgs() {
        Frequency frequency = new Frequency();
        frequency.addValue("test");
        Assert.assertEquals(1, frequency.getCount("test"));
    }
} 
