    public void testBinomialCoefficientLog_NLessThanZero(){
        MathUtils.binomialCoefficientLog(-1,0);
    }

    @Test
    public void testBinomialCoefficientLog_Zero(){
        Assert.assertEquals(0, MathUtils.binomialCoefficientLog(2,2), 0.0001);
        Assert.assertEquals(0, MathUtils.binomialCoefficientLog(5,0), 0.0001);
    }

