    public void testBinomialCoefficientLog_One(){
        Assert.assertEquals(Math.log(5), MathUtils.binomialCoefficientLog(5,1), 0.0001);
        Assert.assertEquals(Math.log(5), MathUtils.binomialCoefficientLog(5,4), 0.0001);
    }

