import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.geometry.Vector;
import org.apache.commons.math3.geometry.euclidean.oned.Euclidean1D;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.partitioning.Embedding;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;

public class LineTest{
private Line line;
    private Vector3D p1;
    private Vector3D p2;
    @Before
    public void init(){
        p1 = new Vector3D(1,2,3);
        p2 = new Vector3D(4,5,6);
        line = new Line(p1,p2);
    }

    @Test
    public void testRevert() {
        Line revertedLine = line.revert();
        assertNotNull(revertedLine);
        assertNotSame(line, revertedLine);
        assertEquals(line.getOrigin(), revertedLine.getOrigin());
        assertEquals(line.getDirection().negate(), revertedLine.getDirection());
    }

    @Test
    public void testRevert_Immutability() {
        Line initialLine = line;
        line.revert();
        assertEquals(initialLine.getDirection(), line.getDirection());
        assertEquals(initialLine.getOrigin(), line.getOrigin());
    }

    @Test
    public void testLineCopy() {
        Line copiedLine = new Line(line);
        assertNotNull(copiedLine);
        assertNotSame(line, copiedLine);
        assertEquals(line.getOrigin(), copiedLine.getOrigin());
        assertEquals(line.getDirection(), copiedLine.getDirection());
    }

    @Test
    public void testGetters() {
        assertNotNull(line.getDirection());
        assertNotNull(line.getOrigin());
    }
}
